mapper.select:

SELECT /* getActiveUserNumbForUpdate */
       USER_NUMB
  FROM TM_USERXM
 WHERE USER_NUMB = #{userNumb}
   AND USER_STAT = #{userStatActive}
   FOR UPDATE



SELECT /* getComplaintReasonCnt */
       COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{complaintReasonCode}
   AND COMD_CODE = #{cmplRson}
   AND USEE_YSNO = #{commYes}




SELECT /* getReportOwnerNumb */
       R.USER_NUMB
  FROM TM_REPORT R
  JOIN TM_USERXM U
    ON U.USER_NUMB = R.USER_NUMB
   AND U.USER_STAT = #{userStatActive}
 WHERE R.REPT_NUMB = #{tagtNumb}
   AND R.PUBC_YSNO = #{commYes}
   AND R.REPT_STAT != #{reportStatRead}





SELECT /* getReplyOwnerNumb */
       R.USER_NUMB
  FROM TB_REPLXX R
  JOIN TM_USERXM U
    ON U.USER_NUMB = R.USER_NUMB
   AND U.USER_STAT = #{userStatActive}
  JOIN TM_REPORT P
    ON P.REPT_NUMB = R.REPT_NUMB
   AND P.PUBC_YSNO = #{commYes}
   AND P.REPT_STAT != #{reportStatRead}
  JOIN TM_USERXM PU
    ON PU.USER_NUMB = P.USER_NUMB
   AND PU.USER_STAT = #{userStatActive}
 WHERE R.REPL_NUMB = #{tagtNumb}
   AND R.DELT_YSNO = #{commNo}

SELECT /* getDupComplaintCnt */
       COUNT(1)
  FROM TH_CMPLNT
 WHERE USER_NUMB = #{userNumb}
   AND TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}

