INSERT INTO TH_CMPLNT (
            USER_NUMB
          , TAGT_TYPE
          , TAGT_NUMB
          , CMPL_RSON
          , CMPL_CNTN
          , CMPL_STAT
) VALUES (
            #{userNumb}
          , #{tagtType}
          , #{tagtNumb}
          , #{cmplRson}
          , #{cmplCntn}
          , #{complaintReceived}
)
